ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_story_2"] = {
{"fw_ld4_story_c_0001","story",2,"reg=civilian,family,worker,rescue",{1,"I'll tell you how I met my wife",2,"Go on",1,"I was changing a flat on the shoulder of Dixie Highway, sweating like a pig",2,"Romantic",1,"She pulled over in a green Buick, said 'you're doing it backwards'",2,"Was she right?",1,"She was right, she changed it in six minutes, I asked for her number, she said 'you owe me a pie'",2,"Did you bake it?",1,"I bought one from Kroger, she knew, married me anyway"}},
{"fw_ld4_story_c_0002","story",2,"reg=civilian,family,worker,rescue",{1,"When I was ten I ran away from home",2,"Where to?",1,"The end of our street, I sat on a stump, ate a peanut butter sandwich",2,"How long?",1,"Forty minutes, then Mama came out in her robe and said 'dinner's ready'",2,"And you went back?",1,"With the crust still in my teeth, she never mentioned it again, and I never ran away again"}},
{"fw_ld4_story_c_0003","story",2,"reg=civilian,family,worker,rescue",{1,"My Granny made quilts, each one told a story",2,"What was yours?",1,"Mine had a rooster on one square, a boat on another, and a tiny red heart in the corner",2,"What did it mean?",1,"She said 'a rooster wakes you up, a boat takes you far, and the heart brings you home'",2,"That's beautiful",1,"It's under a pile of rubble now, I hope the heart is still red"}},
{"fw_ld4_story_c_0004","story",2,"reg=civilian,family,worker,rescue",{1,"I used to have a pickup with a dent in the door",2,"What kind?",1,"A '72 Chevy, blue, with a dent the exact size of my father's head",2,"Your father's head?",1,"He backed into a post, got out, smacked the door, and left a head-shaped dent",2,"He still alive?",1,"I like to think so, I like to think he's smacking doors somewhere"}},
{"fw_ld4_story_c_0005","story",2,"reg=civilian,family,worker,rescue",{1,"My sister taught me to ride a bike",2,"How old were you?",1,"Eight, she ran behind me, holding the seat, then she let go",2,"And you fell?",1,"I didn't even know she let go, I just kept pedaling, straight into the mailbox",2,"Ha",1,"She laughed so hard she cried, and I did too, and we've been best friends since"}},
{"fw_ld4_story_c_0006","story",2,"reg=civilian,family,worker,rescue",{1,"I was a lifeguard one summer",2,"At the lake?",1,"Barkley Lake, in '86, I saved exactly one person, a boy who was playing dead",2,"Playing dead?",1,"Floating face down, for fun, I dove in, hauled him out, he was giggling",2,"Did you yell at him?",1,"I bought him a snow cone, and I told his mother, who yelled more than me"}},
{"fw_ld4_story_c_0007","story",2,"reg=civilian,family,worker,rescue",{1,"Back in school I had a crush on a teacher",2,"Who?",1,"Miss Delaney, history, she wore flowery dresses and smelled like lavender",2,"Did she know?",1,"I wrote her a poem, left it on her desk, she gave me an A and a very kind talking-to",2,"What did the poem say?",1,"'Roses are red, history is long, you're pretty as a rose, and I'm probably wrong'"}},
{"fw_ld4_story_c_0008","story",2,"reg=civilian,family,worker,rescue",{1,"One Christmas, my uncle dressed as Santa",2,"Good for the kids",1,"He was drunk, he fell off the roof, landed in a snowbank, and said 'ho ho ho' like nothing happened",2,"Was he hurt?",1,"Only his dignity, my aunt took photos, they're on the fridge to this day"}},
{"fw_ld4_story_c_0009","story",2,"reg=civilian,family,worker,rescue",{1,"I was in a car accident once, a bad one",2,"When?",1,"Seventh grade, black ice on the ridge road, we spun twice and hit a fence",2,"Were you hurt?",1,"Cuts and bruises, but I remember the quiet afterward, the snow falling on the windshield",2,"Peaceful?",1,"Strangely, like the world pressed pause, I think about that quiet a lot now"}},
{"fw_ld4_story_c_0010","story",2,"reg=civilian,family,worker,rescue",{1,"I had a pet turtle named Hank",2,"Hank the turtle",1,"He lived for 22 years, outlived two dogs and a cat",2,"So what became of him?",1,"He died the week I got my first job, I buried him in a Tupperware under the maple tree",2,"That's lovely",1,"I didn't cry until I got the paycheck, I don't know why"}},
{"fw_ld4_story_c_0011","story",2,"reg=civilian,family,worker,rescue",{1,"The best Thanksgiving I ever had was a bad one",2,"How bad?",1,"The turkey was raw in the middle, the power went out, the dog ate the pie",2,"Sounds awful",1,"We ordered pizza, played cards by candlelight, laughed until our ribs hurt",2,"That's the good kind of bad"}},
{"fw_ld4_story_c_0012","story",2,"reg=civilian,family,worker,rescue",{1,"When I was 19 I hitchhiked to Nashville",2,"With what?",1,"A guitar I couldn't play and eleven dollars",2,"And?",1,"A trucker named Big Earl picked me up, bought me breakfast, gave me his number",2,"Did you call?",1,"Every Christmas, until last year, I hope he's okay"}},
{"fw_ld4_story_c_0013","story",2,"reg=civilian,family,worker,rescue",{1,"Winter of '78 we were snowed in for nine days",2,"Nine?",1,"Dad hauled in firewood, Mom made soup from boiled shoelaces, we told every story we knew",2,"Sounds miserable",1,"It was the best week of my childhood, don't ask me to explain"}},
{"fw_ld4_story_c_0014","story",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"I want to tell you something",2,"Go ahead",1,"The first dead one I saw was a customer at my diner",2,"Regular?",1,"Every morning, black coffee, no sugar, I handed him his cup out of habit",2,"Habit?",1,"It wasn't him anymore, but I handed him the cup anyway, and I'm sorry, I'm still sorry"}},
{"fw_ld4_story_c_0015","story",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"You know why I keep a hat on?",2,"Why?",1,"Because my wife knitted it, and it's the last thing she ever made",2,"I'm sorry",1,"Don't be, it itches like hell, and I'd never take it off"}},
{"fw_ld4_story_c_0016","story",2,"reg=law,swat",{1,"I once talked a man down from a bridge",2,"A suicide?",1,"He had a gun in one hand and a photo in the other, I talked for three hours",2,"How did it end?",1,"He climbed down, I drove him to the hospital, he sent me a postcard every year",2,"Every year?",1,"Same message, 'still here', I hope this year's card is in a mailbox somewhere"}},
{"fw_ld4_story_c_0017","story",2,"reg=law,swat",{1,"My dad was the sheriff before me",2,"Big boots to fill",1,"He used to say 'the badge is heavy only if you carry it alone'",2,"Wise man",1,"He died when I was twenty-six, I've carried it alone ever since"}},
{"fw_ld4_story_c_0018","story",2,"reg=military,elite",{1,"I got a Dear John letter in the Gulf",2,"Ouch",1,"She wrote 'I met someone,' in purple ink, with a smiley face",2,"A smiley face?!",1,"I laughed so hard I cried, then I cried so hard I laughed, the sergeant thought I'd cracked"}},
{"fw_ld4_story_c_0019","story",2,"reg=military,elite",{1,"Best meal of my service was a can of peaches in the desert",2,"Peaches?",1,"We found a crate in an abandoned truck, six of us, one can each",2,"Heaven?",1,"Better, it tasted like home, like Georgia, like my grandma's cobbler"}},
{"fw_ld4_story_c_0020","story",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"I once robbed a bank dressed as a priest",2,"Did it work?",1,"They gave me everything, then asked for a blessing",2,"Did you bless them?",1,"I said 'go in peace,' and ran, I'm still not sure God was amused"}},
{"fw_ld4_story_c_0021","story",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"My brother and I stole a pig once",2,"A pig?",1,"For a bet, a thirty-pound piglet, we put it in a gym bag",2,"And?",1,"It squealed the whole way home, we named it Bacon, it lived to be 400 pounds"}},
{"fw_ld4_story_c_0022","story",2,"reg=family",{1,"When your mother was born, it snowed in June",2,"In June?",1,"A freak storm, the whole county shut down, your Papaw delivered her himself",2,"Delivered her?!",1,"With a pocketknife, a clean towel, and a prayer, he never lived it down"}},
{"fw_ld4_story_c_0023","story",2,"reg=family",{1,"My first dance was at the VFW hall",2,"Who with?",1,"Your grandfather, in a borrowed jacket, with sweaty hands",2,"Did you like him?",1,"Not at first, but he stepped on my foot and said 'sorry' so sincerely, I forgave everything"}},
}
